package com.codeforge.platform.config;

import com.codeforge.platform.entity.OrgMember;
import com.codeforge.platform.entity.Organization;
import com.codeforge.platform.entity.User;
import com.codeforge.platform.mapper.OrgMemberMapper;
import com.codeforge.platform.mapper.OrganizationMapper;
import com.codeforge.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

/**
 * Seeds the baseline accounts and organization on first start. When the
 * {@code admin} user already exists the runner does nothing, so restarts
 * against a populated database neither duplicate rows nor fail.
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final OrganizationMapper organizationMapper;
    private final OrgMemberMapper orgMemberMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           OrganizationMapper organizationMapper,
                           OrgMemberMapper orgMemberMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.organizationMapper = organizationMapper;
        this.orgMemberMapper = orgMemberMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        if (userMapper.findByUsername("admin") != null) {
            return;
        }

        LocalDateTime now = LocalDateTime.now();

        User admin = new User();
        admin.setUsername("admin");
        admin.setPassword(passwordEncoder.encode("admin123"));
        admin.setRole("ADMIN");
        admin.setCreatedAt(now);
        userMapper.insert(admin);

        User alice = new User();
        alice.setUsername("alice");
        alice.setPassword(passwordEncoder.encode("alice123"));
        alice.setRole("USER");
        alice.setCreatedAt(now);
        userMapper.insert(alice);

        Organization organization = new Organization();
        organization.setName("默认团队");
        organization.setDescription("系统默认团队");
        organization.setOwnerId(admin.getId());
        organization.setCreatedAt(now);
        organizationMapper.insert(organization);

        OrgMember member = new OrgMember();
        member.setOrgId(organization.getId());
        member.setUserId(admin.getId());
        member.setMemberRole("ADMIN");
        member.setJoinedAt(now);
        orgMemberMapper.insert(member);
    }
}

package com.codeforge.platform.config;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;

/**
 * Issues and reads the platform's bearer tokens (JJWT). A token carries the
 * username as its subject plus the user's role and numeric id as claims, an
 * issued-at time and an expiration {@code jwt.expiration} milliseconds later,
 * signed with a key derived from {@code jwt.secret}.
 */
@Component
public class JwtUtil {

    private static final String CLAIM_ROLE = "role";
    private static final String CLAIM_USER_ID = "userId";

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.expiration}")
    private long expiration;

    private SecretKey getSigningKey() {
        return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public String generateToken(String username, String role, Long userId) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expiration);
        return Jwts.builder()
                .setSubject(username)
                .claim(CLAIM_ROLE, role)
                .claim(CLAIM_USER_ID, userId)
                .setIssuedAt(now)
                .setExpiration(expiry)
                .signWith(getSigningKey(), SignatureAlgorithm.HS256)
                .compact();
    }

    public boolean validateToken(String token) {
        try {
            parseToken(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public String getUsernameFromToken(String token) {
        return parseToken(token).getSubject();
    }

    public String getRoleFromToken(String token) {
        return parseToken(token).get(CLAIM_ROLE, String.class);
    }

    public Long getUserIdFromToken(String token) {
        Object value = parseToken(token).get(CLAIM_USER_ID);
        if (value == null) {
            return null;
        }
        if (value instanceof Number) {
            return ((Number) value).longValue();
        }
        return Long.valueOf(value.toString());
    }

    public long getExpiration() {
        return expiration;
    }

    private Claims parseToken(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(getSigningKey())
                .build()
                .parseClaimsJws(token)
                .getBody();
    }
}

package com.codeforge.platform.config;

import com.codeforge.platform.filter.JwtAuthFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session ->
                        session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/login", "/api/repos/*/readme").permitAll()
                        .anyRequest().authenticated())
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }
}

